INSERT INTO `articles` (`id`, `type`, `title`, `slug`, `category`, `author`, `date`, `read_time`, `status`, `image`, `excerpt`, `content`, `created_at`) VALUES (1, 'blog', 'Top 7 High-Growth Localities to Buy Property in Pune (2026 Edition)', 'top-high-growth-localities-pune', 'Locality Guide', 'Pune Property Research Team', '2026-10-24', '6 min read', 'Published', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85', 'From Kharadi\'s IT corridor expansion to Baner and Wakad\'s connectivity surge, discover where smart homebuyers and NRI investors are securing highest rental yields.', '<p>Pune\'s real estate landscape continues to outperform tier-1 peers due to balanced IT employment growth, Metro corridors, and integrated township supply.</p>', '2026-11-27 06:22:55') ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);
INSERT INTO `articles` (`id`, `type`, `title`, `slug`, `category`, `author`, `date`, `read_time`, `status`, `image`, `excerpt`, `content`, `created_at`) VALUES (2, 'blog', 'First-Time Homebuyer\'s Checklist: Documents, RERA, and Stamp Duty in Maharashtra', 'first-time-homebuyer-checklist-maharashtra', 'Buying Guide', 'Legal Advisory Desk', '2026-10-18', '5 min read', 'Published', 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1200&q=85', 'A step-by-step roadmap to navigating MahaRERA registration, title clearance verification, home loan eligibility, and government registration fees in Pune.', '<p>Always verify the MahaRERA registration number, sanctioned commencement certificate (CC), and carpet area statement before paying token booking amounts.</p>', '2026-11-27 06:22:55') ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);
